// Cross-language parity with spec/vectors.json (§20), generated by spec/gen_vectors.py.
// Mirrors server/tests/test_vectors.py: every canonical string and digest byte for byte, every
// signature, every rejection and every rule outcome.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { sha256 } from '@noble/hashes/sha2.js';
import { bytesToHex, utf8ToBytes } from '@noble/hashes/utils.js';
import { describe, expect, it } from 'vitest';
import {
  EncodingError, bytes, bytesList, canonicalOf, contactCanonical, contactId, derToRaw, detailsHash,
  dgenCanonical, digest, dlogHash, enumToken, fromFields, fromWire, genCanonical, id8, int, isLowS,
  itemId, logTamper, makeProof, merchantCheck, merchantKnew, normalizeLowS, overCap, payFromWire,
  payToWire, proofCanonical, proofFromWire, proofToWire, rawToDer, rulesFired, equivocation, str, strList,
  tagHash, tagValid, toWire, dlogToWire, dlogFromWire, verifyDigest, verifyDlog, verifyObject,
  type Dlog, type ItemKind, type MCert, type Pay, type Policy, type Proof, type Req, type SchemaType, type Tag,
} from '..';

type J = Record<string, any>;
const V: J = JSON.parse(readFileSync(resolve(__dirname, '../../../../spec/vectors.json'), 'utf8'));

const cases = (name: string): [string, J][] => (V[name] as J[]).map((v) => [v.name, v]);
const obj = <T,>(v: J): T => fromFields<T>(v.type, v.fields, v.sig);
const pay = (v: J): Pay => ({ c: obj(v.c), t: obj(v.t), d: obj(v.d) });

describe('encoding', () => {
  it.each(cases('encoding'))('%s', (_n, v) => {
    const render = (): string => {
      switch (v.kind) {
        case 'bytes': return bytes(v.value, v.size);
        case 'bytes_list': return bytesList(v.value, v.size);
        case 'int': return int(v.value);
        case 'string': return str(v.value);
        case 'enum': return enumToken(v.value, v.allowed);
        default: return strList(v.value);
      }
    };
    if (v.error) expect(render).toThrow(EncodingError);
    else expect(render()).toBe(v.rendered);
  });
});

describe('objects', () => {
  it.each(cases('objects'))('%s', (_n, v) => {
    expect(bytesToHex(sha256(utf8ToBytes(v.canonical)))).toBe(v.digest);
    if (v.type === 'GEN') return expect(genCanonical(v.fields.cert_id)).toBe(v.canonical);
    if (v.type === 'DGEN') return expect(dgenCanonical(v.fields.device_pub)).toBe(v.canonical);

    const o = obj<J>(v);
    const isDlog = v.type === 'DLOG';
    expect(canonicalOf(v.type, o as never)).toBe(v.canonical);
    expect(isDlog ? dlogHash(o as Dlog) : digest(v.type as SchemaType, o)).toBe(v.digest);

    // Transport JSON: exact encoding and lossless round trip.
    const wire = isDlog ? dlogToWire(o as Dlog) : toWire(v.type, o);
    expect(wire).toEqual(v.json);
    expect(isDlog ? dlogFromWire(v.json) : fromWire(v.type, v.json)).toEqual(o);

    if (v.pub !== null) {
      const ok = isDlog ? verifyDlog(o as Dlog) : verifyObject(v.type, o, v.pub);
      expect(ok).toBe(v.valid);
      if (v.valid) expect(isLowS(o.sig)).toBe(true);
    } else {
      expect(v.valid && v.sig === null).toBe(true);
    }
    if ('item_kind' in v) {
      const full = itemId(v.item_kind as ItemKind, o as never);
      expect(full).toBe(v.item_id);
      expect(id8(full)).toBe(v.id8);
    }
  });
});

describe('pays', () => {
  it.each(cases('pays'))('%s', (_n, v) => {
    const p = pay(v);
    expect(payToWire(p)).toEqual(v.json);
    expect(payFromWire(v.json)).toEqual(p);
    expect(itemId('PAY', p)).toBe(v.item_id);
    expect(tagHash(p.t)).toBe(v.item_id);
    expect(itemId('TAG', p.t)).toBe(itemId('PAY', p));
    expect(id8(itemId('PAY', p))).toBe(v.id8);
    expect(p.t.details_hash).toBe(detailsHash(p.d));
  });
});

describe('signatures', () => {
  it.each(cases('signatures'))('%s', (_n, v) => {
    expect(verifyDigest(v.sig, v.digest, v.pub)).toBe(v.valid);
    if (v.valid) expect(isLowS(v.sig)).toBe(v.low_s);
  });
  it('includes a valid high-S signature', () => {
    expect(V.signatures.some((v: J) => v.valid && !v.low_s)).toBe(true);
  });
});

describe('der', () => {
  it.each(cases('der'))('%s', (_n, v) => {
    const raw = derToRaw(v.der);
    expect(raw).toBe(v.raw);
    expect(normalizeLowS(raw)).toBe(v.raw_low_s);
    expect(rawToDer(raw)).toBe(v.der);
    expect(verifyDigest(raw, v.digest, v.pub)).toBe(true);
    expect(verifyDigest(v.raw_low_s, v.digest, v.pub)).toBe(true);
  });
});

describe('contact ids', () => {
  it.each(cases('contact_ids'))('%s', (_n, v) => {
    const { a, b } = v;
    expect(contactId(a.pub, a.nonce, b.pub, b.nonce)).toBe(v.contact_id);
    expect(contactId(b.pub, b.nonce, a.pub, a.nonce)).toBe(v.contact_id);
    expect(contactCanonical(a.pub, a.nonce, b.pub, b.nonce)).toBe(v.canonical);
  });
});

describe('rules', () => {
  it.each(cases('single_tag'))('single tag %s', (_n, v) => {
    expect(tagValid(obj<Tag>(v.tag))).toBe(v.valid);
  });

  it.each(cases('equivocation'))('equivocation %s', (_n, v) => {
    const a = obj<Tag>(v.a), b = obj<Tag>(v.b);
    expect(rulesFired(a, b)).toEqual(v.rules_fired);
    expect(rulesFired(b, a)).toEqual(v.rules_fired);
    expect(equivocation(a, b)).toBe(v.rule);
    expect(makeProof(a, b)?.rule ?? null).toBe(v.rule);
  });

  it.each(cases('proofs'))('proof %s', async (_n, v) => {
    const { verifyProof } = await import('../rules');
    const p: Proof = { a: obj(v.a), b: obj(v.b), rule: v.rule };
    expect(proofToWire(p)).toEqual(v.json);
    expect(proofFromWire(v.json)).toEqual(p);
    expect(verifyProof(p, v.holder_pub)).toBe(v.valid);
    expect(proofCanonical(tagHash(p.a), tagHash(p.b))).toBe(v.canonical);
    expect(itemId('PROOF', p)).toBe(v.item_id);
  });

  it.each(cases('merchant_checks'))('merchant check %s', (_n, v) => {
    const r = merchantCheck(pay(v.pay), {
      serverPub: v.server_pub,
      merchant: obj<MCert>(v.merchant),
      req: obj<Req>(v.req),
      policy: v.policy === null ? null : obj<Policy>(v.policy),
      storedTags: v.stored_tags.map((t: J) => obj<Tag>(t)),
      now: v.now,
    });
    const e = v.expect;
    expect(r.ok).toBe(e.ok);
    expect(r.ok ? null : r.check).toBe(e.check);
    expect(r.ok ? null : r.reason).toBe(e.reason);
    expect(r.ok ? null : r.rule).toBe(e.rule);
    expect(r.ok || !r.conflict ? null : tagHash(r.conflict)).toBe(e.conflict);
  });

  it.each(cases('over_cap'))('over cap %s', (_n, v) => {
    const settled: Tag[] = [];
    for (const step of v.steps) {
      settled.push(obj<Tag>(step.tag));
      expect(overCap(settled, v.caps)).toBe(step.over_cap);
    }
  });

  it.each(cases('log_tamper'))('log tamper %s', (_n, v) => {
    const entries = v.entries.map((e: J) => obj<Dlog>(e));
    expect(entries.every(verifyDlog)).toBe(true);
    expect(logTamper(entries)).toEqual(v.expect);
  });

  it.each(cases('merchant_knew'))('merchant knew %s', (_n, v) => {
    const logs = v.logs.map((e: J) => obj<Dlog>(e));
    expect(logs.every(verifyDlog)).toBe(true);
    const got = merchantKnew(obj<Tag>(v.z), {
      merchantPub: v.merchant_pub, tAccept: v.t_accept, certTags: v.cert_tags.map((t: J) => obj<Tag>(t)), logs,
    });
    expect(got !== null).toBe(v.expect.fired);
    if (got) {
      expect(got.clause).toBe(v.expect.clause);
      expect(got.conflict).toBe(v.expect.conflict);
      expect(got.contactId).toBe(v.expect.contact_id);
    }
  });
});
